{"pasos": [
  {"id": "s1", "op": "search_catalog", "args": {"query": "televisor", "category": "televisores", "max_price": 1342000, "attributes": {"pulgadas": {"min": 55}}, "limit": 5}},
  {"id": "s2", "op": "compare_products", "args": {"ids": ["$s1.0.id", "$s1.1.id", "$s1.2.id"]}},
